$ErrorActionPreference = 'Stop'
$result = foreach ($directory in Get-ChildItem -LiteralPath $PSScriptRoot -Directory | Where-Object Name -Match '^\d{2}-.*-trace$' | Sort-Object Name) {
    $path = @(Get-ChildItem -LiteralPath $directory.FullName -Filter '*.events.json')
    if ($path.Count -ne 1) { throw 'Missing parsed trace' }
    $trace = Get-Content -LiteralPath $path[0].FullName -Raw | ConvertFrom-Json
    if ($trace.EventsLost -ne 0) { throw 'Trace lost events' }
    $starts = @{}; $compilers = @{}; $windowCounts = @{}; $pending = $null
    $versions = [Collections.Generic.List[object]]::new()
    $windows = [Collections.Generic.List[object]]::new()
    foreach ($event in $trace.Events) {
        if ($event.ProviderName -eq 'BenchmarkDotNet.EngineEventSource') {
            if ($event.Id -in @(5,13,15)) { $pending = $event }
            if ($event.Id -in @(6,14,16)) {
                if ($null -eq $pending -or $pending.Id+1 -ne $event.Id) { throw 'Unpaired workload window' }
                $stage = ($pending.EventName -split '/')[0]
                $windowCounts[$stage] = 1 + $windowCounts[$stage]
                $windows.Add([pscustomobject]@{Stage=$stage;Iteration=$windowCounts[$stage];StartMs=$pending.TimeMs;StopMs=$event.TimeMs
                    StartUtc=$pending.Utc;StopUtc=$event.Utc;Operations=[int]$event.Payload.totalOperations
                    MeanMs=($event.TimeMs-$pending.TimeMs)/[int]$event.Payload.totalOperations})
                $pending = $null
            }
        }
        if ($event.EventName -eq 'Method/JittingStarted') {
            $item = [pscustomobject]@{Event=$event;Inlines=[Collections.Generic.List[object]]::new()}
            $starts[$event.Payload.MethodID] = $item
            $compilers[$event.ThreadID] = $item
        }
        if ($event.EventName -in @('Method/InliningSucceeded','Method/InliningFailed') -and $event.Payload.MethodBeingCompiledNamespace -like 'Marimo.*') {
            $compiler = $compilers[$event.ThreadID]
            if ($null -eq $compiler -or $compiler.Event.Payload.MethodNamespace -ne $event.Payload.MethodBeingCompiledNamespace -or
                $compiler.Event.Payload.MethodName -ne $event.Payload.MethodBeingCompiledName) { throw 'Inline root mismatch' }
            $compiler.Inlines.Add([pscustomobject]@{TimeMs=$event.TimeMs;Outcome=$event.EventName
                Inliner=$event.Payload.InlinerNamespace+':'+$event.Payload.InlinerName
                Inlinee=$event.Payload.InlineeNamespace+':'+$event.Payload.InlineeName;Reason=$event.Payload.FailReason})
        }
        if ($event.EventName -eq 'Method/LoadVerbose' -and $event.Payload.MethodNamespace -like 'Marimo.*') {
            $start = $starts[$event.Payload.MethodID]
            $versions.Add([pscustomobject]@{Method=$event.Payload.MethodNamespace+':'+$event.Payload.MethodName
                Tier=$event.Payload.OptimizationTier;StartMs=$start.Event.TimeMs;LoadMs=$event.TimeMs
                NativeBytes=[int]$event.Payload.MethodSize;ReJit=$event.Payload.ReJITID;Inlines=@($start.Inlines.ToArray())})
        }
    }
    $record = Get-Content -LiteralPath "$($directory.FullName)/record.json" -Raw | ConvertFrom-Json
    if ($null -ne $pending -or @($windows | Where-Object Stage -EQ 'WorkloadActual').Count -ne $record.IterationCount -or
        @($windows | Where-Object Stage -EQ 'WorkloadWarmup').Count -ne $record.WarmupCount) { throw 'Incomplete workload windows' }
    [pscustomobject]@{Run=$directory.Name;EventsLost=$trace.EventsLost;EventCount=$trace.EventCount;Windows=$windows.ToArray();Versions=$versions.ToArray()}
}
$output = Join-Path $PSScriptRoot 'tier-timelines.json'
if (Test-Path -LiteralPath $output) { throw 'Timelines already exist' }
[IO.File]::WriteAllText($output,(($result|ConvertTo-Json -Depth 10).Replace("`r`n","`n")+"`n"),[Text.UTF8Encoding]::new($false))
foreach ($run in $result) {
    $run.Versions | Where-Object Method -Match 'ZeroOrMoreParser`1\[System.Char\]:ParseCore$|OrParser`1\[System.Char\]:ParseCore$|Parser`1\[System.Char\]:Parse$' |
        Select-Object @{N='Run';E={$run.Run}},Method,Tier,StartMs,LoadMs,NativeBytes | ConvertTo-Json
    $run.Windows | Where-Object { $_.Stage -eq 'WorkloadWarmup' -and $_.Iteration -le 3 -or $_.Stage -eq 'WorkloadActual' -and $_.Iteration -eq 1 } | ConvertTo-Json
}

$ErrorActionPreference='Stop'
function Stats([double[]]$Values){
    if($Values.Count -lt 2){throw 'Not enough values'}
    $mean=($Values|Measure-Object -Average).Average
    $sd=[Math]::Sqrt((($Values|ForEach-Object{[Math]::Pow($_-$mean,2)}|Measure-Object -Sum).Sum)/($Values.Count-1))
    [pscustomobject]@{N=$Values.Count;Mean=$mean;SD=$sd;CV=100*$sd/$mean;Min=($Values|Measure-Object -Minimum).Minimum;Max=($Values|Measure-Object -Maximum).Maximum}
}
$plan=@(Get-Content -Raw -LiteralPath "$PSScriptRoot/plan.json"|ConvertFrom-Json)
$runs=@(foreach($case in $plan){
    $record=Get-Content -Raw -LiteralPath "$PSScriptRoot/$($case.Run)/record.json"|ConvertFrom-Json
    if($record.Run -ne $case.Run -or $record.N -ne $case.Actual -or $record.ExitCode -ne 0){throw 'Run mismatch'}
    $values=@($record.Iterations|Where-Object Stage -eq 'Result'|ForEach-Object{$_.TotalNanoseconds/$_.Operations/1e6})
    $s=Stats $values
    if([Math]::Abs($s.Mean-$record.MeanMs) -gt 1e-8){throw 'Mean mismatch'}
    $half=$values.Count/2
    $early=($values[0..($half-1)]|Measure-Object -Average).Average
    $late=($values[$half..($values.Count-1)]|Measure-Object -Average).Average
    $record|Add-Member -NotePropertyName DriftPercent -NotePropertyValue (100*($late/$early-1))
    $record|Add-Member -NotePropertyName IterationCV -NotePropertyValue $s.CV
    $record
})
$groups=@(foreach($variant in 'baseline','callsite'){
    foreach($profile in 'reference','short','settled'){
        $rows=@($runs|Where-Object{$_.Variant -eq $variant -and $_.Profile -eq $profile -and $_.Diagnostics -eq 'plain'})
        $s=Stats @($rows.MeanMs)
        $meanCV=($rows.IterationCV|Measure-Object -Average).Average
        [pscustomobject]@{Variant=$variant;Profile=$profile;N=$s.N;MeanMs=$s.Mean;LaunchCV=$s.CV;MinMs=$s.Min;MaxMs=$s.Max;MeanIterationCV=$meanCV
            MeanWallSeconds=($rows.WallSeconds|Measure-Object -Average).Average;DriftFlags=@($rows|Where-Object{[Math]::Abs($_.DriftPercent) -gt 3}).Count
            StabilityPass=($s.CV -le 3 -and $meanCV -le 5)}
    }
})
$equivalence=@(foreach($variant in 'baseline','callsite'){
    foreach($profile in 'short','settled'){
        $logs=@(foreach($block in 1..8){
            $r=@($runs|Where-Object{$_.Variant -eq $variant -and $_.Block -eq $block -and $_.Profile -eq 'reference'})
            $c=@($runs|Where-Object{$_.Variant -eq $variant -and $_.Block -eq $block -and $_.Profile -eq $profile})
            if($r.Count -ne 1 -or $c.Count -ne 1){throw 'Missing paired block'}
            [Math]::Log($c[0].MeanMs/$r[0].MeanMs)
        })
        $s=Stats $logs;$margin=2.364624251*$s.SD/[Math]::Sqrt(8)
        $lower=[Math]::Exp($s.Mean-$margin);$upper=[Math]::Exp($s.Mean+$margin)
        [pscustomobject]@{Variant=$variant;Profile=$profile;Ratio=[Math]::Exp($s.Mean);Lower95=$lower;Upper95=$upper;WithinThreePercent=($lower -ge 0.97 -and $upper -le 1.03)}
    }
})
$aa=@(foreach($profile in 'reference','short','settled'){
    $odd=@($runs|Where-Object{$_.Variant -eq 'callsite' -and $_.Profile -eq $profile -and $_.Block%2 -eq 1}|ForEach-Object{[Math]::Log($_.MeanMs)})
    $even=@($runs|Where-Object{$_.Variant -eq 'callsite' -and $_.Profile -eq $profile -and $_.Block -gt 0 -and $_.Block%2 -eq 0}|ForEach-Object{[Math]::Log($_.MeanMs)})
    $a=Stats $odd;$b=Stats $even
    $se=[Math]::Sqrt($a.SD*$a.SD/4+$b.SD*$b.SD/4)
    $margin=3.182446305*$se
    [pscustomobject]@{Profile=$profile;Ratio=[Math]::Exp($b.Mean-$a.Mean);Lower95Conservative=[Math]::Exp($b.Mean-$a.Mean-$margin);Upper95Conservative=[Math]::Exp($b.Mean-$a.Mean+$margin);Method='Log means, independent groups n=4/4, conservative t critical df=3'}
})
$truncation=@(foreach($run in $runs|Where-Object{$_.Profile -eq 'reference' -and $_.Diagnostics -eq 'plain'}){
    $first=@($run.Iterations|Where-Object{$_.Stage -eq 'Result' -and $_.Iteration -le 8}|ForEach-Object{$_.TotalNanoseconds/$_.Operations/1e6})
    [pscustomobject]@{Run=$run.Run;Variant=$run.Variant;First8VsFull16Percent=100*(($first|Measure-Object -Average).Average/$run.MeanMs-1)}
})
$output=[ordered]@{Runs=$runs;Groups=$groups;Equivalence=$equivalence;SameBinaryAA=$aa;RetrospectiveTruncation=$truncation}
[IO.File]::WriteAllText("$PSScriptRoot/analysis.json",(($output|ConvertTo-Json -Depth 9).Replace("`r`n","`n")+"`n"),[Text.UTF8Encoding]::new($false))
$groups|Format-Table -AutoSize
$equivalence|Format-Table -AutoSize
$aa|Format-Table -AutoSize

param([switch]$ValidateOnly)
$ErrorActionPreference = 'Stop'
$experiment = '2026-10-05-measurement-method'
$repoRoot = (Resolve-Path "$PSScriptRoot/../..").Path
$target = Join-Path $repoRoot 'Kotowari.Benchmarks/Results/word-parser'
$records = @((Get-Content -LiteralPath "$PSScriptRoot/analysis.json" -Raw | ConvertFrom-Json).Runs)
if ($records.Count -ne 52) { throw 'Expected all 52 scheduled processes' }
$summaries = [Collections.Generic.List[object]]::new()
$iterations = [Collections.Generic.List[object]]::new()
$launches = [Collections.Generic.List[object]]::new()
foreach ($record in $records) {
    $kind = 'pgo-on-method-' + $record.Profile + $(if ($record.Diagnostics -eq 'trace') {'-eventpipe'} else {''})
    $environment = '.NET 10.0.12; ' + $kind + '; Balanced; HighPriority; NoAcknowledgementConsoleHost'
    $base = [ordered]@{Experiment=$experiment;Run=$record.Run;Variant=$record.Variant;Benchmark='JsonParserBenchmarks.Kotowari';Parameters=''}
    $values = @($record.Iterations | Where-Object Stage -EQ 'Result' | ForEach-Object { $_.TotalNanoseconds/$_.Operations } | Sort-Object)
    if ($values.Count -ne $record.IterationCount) { throw 'Wrong result count' }
    $mean = ($values|Measure-Object -Average).Average
    if ([Math]::Abs($mean/1e6-$record.MeanMs) -gt 1e-8) { throw 'Mean mismatch' }
    $sd = [Math]::Sqrt((($values|ForEach-Object{[Math]::Pow($_-$mean,2)}|Measure-Object -Sum).Sum)/($values.Count-1))
    $memory = $record.AllocatedTotalBytes/$record.GcOperations
    $job = 'FixedBDN0.15.8; PGO=1; WarmupCount=' + $record.WarmupCount + '; IterationCount=' + $record.IterationCount + '; InvocationCount=4; UnrollFactor=1; OutlierMode=DontRemove; Affinity=4; Priority=High; Power=Balanced; Profile=' + $record.Profile + '; Diagnostics=' + $record.Diagnostics
    $row = [ordered]@{}; foreach ($key in $base.Keys) {$row[$key]=$base[$key]}
